class Solution {
    public int goodNodes(TreeNode root) {
        return dfs(root, Integer.MIN_VALUE);
    }

    private int dfs(TreeNode node, int maxSoFar) {
        if (node == null) return 0;

        int count = node.val >= maxSoFar ? 1 : 0;
        int nextMax = Math.max(maxSoFar, node.val);
        count += dfs(node.left, nextMax);
        count += dfs(node.right, nextMax);
        return count;
    }
}

class Solution {
    private int count;

    public int goodNodes(TreeNode root) {
        count = 0;
        visit(root, Integer.MIN_VALUE);
        return count;
    }

    private void visit(TreeNode node, int maxSoFar) {
        if (node == null) return;

        if (node.val >= maxSoFar) {
            count++;
        }
        int nextMax = Math.max(maxSoFar, node.val);
        visit(node.left, nextMax);
        visit(node.right, nextMax);
    }
}

import java.util.*;

class Solution {
    public int goodNodes(TreeNode root) {
        if (root == null) return 0;

        int count = 0;
        Queue<Frame> queue = new ArrayDeque<>();
        queue.offer(new Frame(root, Integer.MIN_VALUE));

        while (!queue.isEmpty()) {
            Frame current = queue.poll();
            TreeNode node = current.node;
            if (node.val >= current.pathMax) {
                count++;
            }
            int nextMax = Math.max(current.pathMax, node.val);
            if (node.left != null) queue.offer(new Frame(node.left, nextMax));
            if (node.right != null) queue.offer(new Frame(node.right, nextMax));
        }

        return count;
    }

    private static class Frame {
        TreeNode node;
        int pathMax;

        Frame(TreeNode node, int pathMax) {
            this.node = node;
            this.pathMax = pathMax;
        }
    }
}

import java.util.*;

class Solution {
    public int goodNodes(TreeNode root) {
        if (root == null) return 0;

        int count = 0;
        Deque<TreeNode> nodeStack = new ArrayDeque<>();
        Deque<Integer> maxStack = new ArrayDeque<>();
        nodeStack.push(root);
        maxStack.push(Integer.MIN_VALUE);

        while (!nodeStack.isEmpty()) {
            TreeNode node = nodeStack.pop();
            int pathMax = maxStack.pop();
            if (node.val >= pathMax) {
                count++;
            }
            int nextMax = Math.max(pathMax, node.val);
            if (node.left != null) {
                nodeStack.push(node.left);
                maxStack.push(nextMax);
            }
            if (node.right != null) {
                nodeStack.push(node.right);
                maxStack.push(nextMax);
            }
        }

        return count;
    }
}
